package net.officefloor.hq.app.history;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.PersonGrade;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.SettingValue;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/** The sheet as it stood at the end of a past day, read back from the states its claims, rates,
 *  grades, dated settings and policy date were saved in: every change made while the sheet's today
 *  was on or before that day counts, every later change does not. What is read back is a copy that
 *  is never saved. */
@Service
public class History {

    private final JdbcTemplate jdbc;

    public History(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The claim as it stood at the end of a day; empty when it had not been added by then. */
    public Optional<Claim> claim(Long claimId, LocalDate day) {
        return jdbc.query("SELECT * FROM claim_history WHERE claim_id = ? AND made_on <= ? ORDER BY id DESC LIMIT 1",
                (rs, n) -> Claim.asItWas(rs.getLong("claim_id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                        rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
                        rs.getObject("due_by", LocalDate.class), ClaimStatus.valueOf(rs.getString("status")),
                        rs.getBigDecimal("settled_due"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
                        rs.getString("corrects_number"), rs.getObject("deferred_until", LocalDate.class)),
                claimId, day).stream().findFirst();
    }

    /** A grade's rates on the sheet as they stood at the end of a day: for each from-date, the rate
     *  last set from it by then. */
    public List<Rate> rates(String sheetId, String grade, LocalDate day) {
        Map<LocalDate, Rate> byFrom = new LinkedHashMap<>();
        jdbc.query("SELECT * FROM rate_history WHERE sheet_id = ? AND grade = ? AND made_on <= ? ORDER BY id",
                (rs, n) -> new Rate(sheetId, grade, rs.getObject("from_date", LocalDate.class),
                        rs.getObject("to_date", LocalDate.class), rs.getBigDecimal("rate")),
                sheetId, grade, day).forEach(rate -> byFrom.put(rate.getFrom(), rate));
        return new ArrayList<>(byFrom.values());
    }

    /** A person's grades as they stood at the end of a day: for each from-date, the grade last given
     *  from it by then. */
    public List<PersonGrade> grades(Long personId, LocalDate day) {
        Map<LocalDate, PersonGrade> byFrom = new LinkedHashMap<>();
        jdbc.query("SELECT * FROM person_grade_history WHERE person_id = ? AND made_on <= ? ORDER BY id",
                (rs, n) -> new PersonGrade(rs.getString("sheet_id"), personId, rs.getString("grade"),
                        rs.getObject("from_date", LocalDate.class)),
                personId, day).forEach(grade -> byFrom.put(grade.getFrom(), grade));
        return new ArrayList<>(byFrom.values());
    }

    /** The value of a dated setting in force on a date as the values stood at the end of a day: of
     *  the value last recorded from each from-date by then, the one with the latest from-date on or
     *  before the date; empty before every from-date. */
    public Optional<SettingValue> setting(String sheetId, String key, LocalDate on, LocalDate day) {
        Map<LocalDate, SettingValue> byFrom = new LinkedHashMap<>();
        jdbc.query("SELECT * FROM sheet_setting_value_history WHERE sheet_id = ? AND setting_key = ? AND made_on <= ?"
                        + " ORDER BY id",
                (rs, n) -> new SettingValue(sheetId, key, rs.getObject("from_date", LocalDate.class),
                        rs.getBigDecimal("setting_value")),
                sheetId, key, day).forEach(value -> byFrom.put(value.getFrom(), value));
        return byFrom.values().stream().filter(value -> !value.getFrom().isAfter(on))
                .max((a, b) -> a.getFrom().compareTo(b.getFrom()));
    }

    /** Keep the sheet's policy date as it is now set (null: blank), with the sheet's today. */
    public void policyDateSet(String sheetId) {
        jdbc.update("INSERT INTO sheet_policy_date_history (sheet_id, policy_date, made_on)"
                + " SELECT id, policy_date, today FROM sheet WHERE id = ?", sheetId);
    }

    /** The sheet's policy date as it stood set at the end of a day; null when it was blank. */
    public LocalDate policyDate(String sheetId, LocalDate day) {
        List<LocalDate> set = jdbc.query("SELECT policy_date FROM sheet_policy_date_history WHERE sheet_id = ?"
                        + " AND made_on <= ? ORDER BY id DESC LIMIT 1",
                (rs, n) -> rs.getObject("policy_date", LocalDate.class), sheetId, day);
        return set.isEmpty() ? null : set.get(0);
    }
}
package net.officefloor.hq.app.history;

import jakarta.persistence.PostPersist;
import jakarta.persistence.PostUpdate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.person.PersonGrade;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.SettingValue;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.jdbc.core.JdbcTemplate;

/** Keeps each state a claim, a rate, a person's grade or a dated setting is saved in, with the
 *  sheet's today when it was saved, so the sheet can be read as it stood at the end of a past day
 *  (see {@link History}). Written in the same transaction as the save itself. */
public class HistoryListener {

    private static final String CLAIM = "INSERT INTO claim_history (claim_id, sheet_id, person_id, amount,"
            + " claim_date, due_by, status, settled_due, stated, stated_due, corrects_number, deferred_until, made_on)"
            + " SELECT c.id, c.sheet_id, c.person_id, c.amount, c.claim_date, c.due_by, c.status, c.settled_due,"
            + " c.stated, c.stated_due, c.corrects_number, c.deferred_until, s.today"
            + " FROM claim c JOIN sheet s ON s.id = c.sheet_id WHERE c.id = ?";

    private static final String RATE = "INSERT INTO rate_history (sheet_id, grade, from_date, to_date, rate, made_on)"
            + " SELECT r.sheet_id, r.grade, r.from_date, r.to_date, r.rate, s.today"
            + " FROM rate r JOIN sheet s ON s.id = r.sheet_id WHERE r.id = ?";

    private static final String GRADE = "INSERT INTO person_grade_history (sheet_id, person_id, grade, from_date, made_on)"
            + " SELECT g.sheet_id, g.person_id, g.grade, g.from_date, s.today"
            + " FROM person_grade g JOIN sheet s ON s.id = g.sheet_id WHERE g.id = ?";

    private static final String SETTING = "INSERT INTO sheet_setting_value_history (sheet_id, setting_key, from_date,"
            + " setting_value, made_on) SELECT v.sheet_id, v.setting_key, v.from_date, v.setting_value, s.today"
            + " FROM sheet_setting_value v JOIN sheet s ON s.id = v.sheet_id WHERE v.id = ?";

    private final ObjectProvider<JdbcTemplate> jdbc;

    public HistoryListener(ObjectProvider<JdbcTemplate> jdbc) {
        this.jdbc = jdbc;
    }

    @PostPersist
    @PostUpdate
    void saved(Object entity) {
        if (entity instanceof Claim claim) {
            jdbc.getObject().update(CLAIM, claim.getId());
        } else if (entity instanceof Rate rate) {
            jdbc.getObject().update(RATE, rate.getId());
        } else if (entity instanceof PersonGrade grade) {
            jdbc.getObject().update(GRADE, grade.getId());
        } else if (entity instanceof SettingValue value) {
            jdbc.getObject().update(SETTING, value.getId());
        }
    }
}
package net.officefloor.hq.app.statement;

/** Only a steward cancels a statement, and only a person with one has a statement to cancel. */
public class StatementCancelRefusedException extends RuntimeException {

    public StatementCancelRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people/{personId}/statement")
public class StatementController {

    /** A statement taken: the person's statements as their row shows them, and their claims,
     *  newest first, as it bound them. */
    public record StatementTaken(StatementSummary statements, List<ClaimView> claims) {
    }

    /** A statement to take: as of a day (blank: now). */
    public record StatementRequest(LocalDate asOf) {
    }

    private final StatementService service;

    private final RollupService rollups;

    private final ClaimService claimService;

    public StatementController(StatementService service, RollupService rollups, ClaimService claimService) {
        this.service = service;
        this.rollups = rollups;
        this.claimService = claimService;
    }

    /** Take a statement for the person, now or as of a day. */
    @PostMapping
    public StatementTaken take(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody(required = false) StatementRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        LocalDate asOf = request != null ? request.asOf() : null;
        List<ClaimView> claims = rollups.track(sheet, by, () -> service.take(sheet, by, personId, asOf)).stream()
                .map(claim -> ClaimView.of(claim, claimService.roundsBy(sheet, claim),
                        claimService.logOf(claim.getId()))).toList();
        return new StatementTaken(service.summary(sheet, personId), claims);
    }

    /** Cancel the person's last statement: their statements as their row then shows them, and their
     *  claims, newest first, now live again. */
    @DeleteMapping
    public StatementTaken cancel(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        List<ClaimView> claims = rollups.track(sheet, by, () -> service.cancel(sheet, by, personId)).stream()
                .map(claim -> ClaimView.of(claim, claimService.roundsBy(sheet, claim),
                        claimService.logOf(claim.getId()))).toList();
        return new StatementTaken(service.summary(sheet, personId), claims);
    }

    @ExceptionHandler(StatementRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refusedAsOf() {
    }

    @ExceptionHandler(StatementCancelRefusedException.class)
    @ResponseStatus(HttpStatus.FORBIDDEN)
    public void refused() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
