241	import java.util.List;
242	import java.util.Map;
243	import java.util.NoSuchElementException;
244	import java.util.Objects;
245	import java.util.Set;
246	import java.util.stream.Collectors;
247	import net.officefloor.hq.app.Audit;
248	import net.officefloor.hq.app.sheet.SheetService;
249	import org.springframework.stereotype.Service;
250	import org.springframework.transaction.annotation.Transactional;
251	
252	/** The people kept on a sheet. */
253	@Service
254	public class PersonService {
255	
256	    private final PersonRepository people;
257	    private final PersonPatronRepository patrons;
258	    private final PersonGradeService grades;
259	    private final PersonHoldRepository holds;
260	    private final PersonWatchRepository watches;
261	    private final SheetService sheets;
262	    private final EntityManager entityManager;
263	    private final Audit audit;
264	
265	    public PersonService(PersonRepository people, PersonPatronRepository patrons, PersonGradeService grades,
266	            PersonHoldRepository holds, PersonWatchRepository watches, SheetService sheets,
267	            EntityManager entityManager, Audit audit) {
268	        this.people = people;
269	        this.watches = watches;
270	        this.patrons = patrons;
271	        this.grades = grades;
272	        this.holds = holds;
273	        this.entityManager = entityManager;
274	        this.sheets = sheets;
275	        this.audit = audit;
276	    }
277	
278	    /** The sheet's people in the order they were added. */
279	    public List<Person> list(String sheetId) {
280	        return people.findBySheetIdOrderByIdAsc(sheetId);
281	    }
282	
283	    /** Add a person to the sheet; the grade they are given applies from the beginning of time. */
284	    @Transactional
285	    public Person add(String sheetId, String user, String name, String grade) {
286	        return add(sheetId, user, name, grade, null);
287	    }
288	
289	    /** Add a person to the sheet with their own terms (null for none); the grade they are given
290	     *  applies from the beginning of time. */
291	    @Transactional
292	    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
293	        LocalDate today = sheets.today(sheetId);
294	        String trimmed = name.trim();
295	        requireFreeName(sheetId, trimmed, null);
296	        Person person = new Person(sheetId, trimmed, today);
297	        person.setTerms(terms);
298	        Person added = people.saveAndFlush(person);
299	        grades.give(added, grade, null);
300	        record("PERSON_ADDED", sheetId, user, added, grade, terms != null ? " terms=" + terms : "");
301	        return added;
302	    }
303	
304	    /** Change a person's name, and give them the grade from a date (blank takes the sheet's today),
305	     *  keeping the grades already given, and set their own terms (null for none), from an editor that loaded the given version of them. A
306	     *  blank from-date with the grade in force on the sheet's today gives no grade. */
307	    @Transactional
308	    public Person update(String sheetId, String user, Long id, long version, String name, String grade,
309	            LocalDate gradeFrom, Integer terms) {
310	        Person person = people.findByIdAndSheetId(id, sheetId)
311	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
312	        if (person.getVersion() != version) {
313	            throw new StalePersonException(person);
314	        }
315	        String trimmed = name.trim();
316	        requireFreeName(sheetId, trimmed, id);
317	        person.setName(trimmed);
318	        Integer before = person.getTerms();
319	        person.setTerms(terms);
320	        LocalDate today = sheets.today(sheetId);
321	        if (gradeFrom != null || !grade.equals(grades.gradeOn(id, today))) {
322	            grades.give(person, grade, gradeFrom != null ? gradeFrom : today);
323	            // A grade given changes the person, so an editor that loaded them before is stale.
324	            entityManager.lock(person, LockModeType.PESSIMISTIC_FORCE_INCREMENT);
325	        }
326	        Person saved = people.saveAndFlush(person);
327	        record("PERSON_EDITED", sheetId, user, saved, grades.gradeOn(id, today),
328	                Objects.equals(before, terms) ? "" : " terms=" + (terms != null ? terms : ""));
329	        return saved;
330	    }
331	
332	    /** Retire a person from a date; a missing date takes the sheet's today. */
333	    @Transactional
334	    public Person retire(String sheetId, String user, Long id, LocalDate from) {
335	        Person person = people.findByIdAndSheetId(id, sheetId)
336	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
337	        LocalDate on = from != null ? from : sheets.today(sheetId);
338	        person.setRetiredFrom(on);
339	        Person saved = people.saveAndFlush(person);
340	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
341	                + " from=" + on);
342	        return saved;
343	    }
344	
345	    /** Put a hold on a person from a date (a missing date takes the sheet's today) to an optional
346	     *  to-date, keeping the holds they have; refused when the to-date is before the from-date. */
347	    @Transactional
348	    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
349	        Person person = people.findByIdAndSheetId(id, sheetId)
350	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
351	        LocalDate on = from != null ? from : sheets.today(sheetId);
352	        if (to != null && to.isBefore(on)) {
353	            throw new HoldRefusedException("The hold's to-date " + to + " is before its from-date " + on);
354	        }
355	        holds.saveAndFlush(new PersonHold(sheetId, id, on, to, sheets.today(sheetId)));
356	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + person.getName()
357	                + " from=" + on);
358	        return person;
359	    }
360	
361	    /** Each person's holds on the sheet, in the order they were put on, by person id; a person with
362	     *  none is absent. */
363	    public Map<Long, List<PersonHold>> holds(String sheetId) {
364	        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
365	                .collect(Collectors.groupingBy(PersonHold::getPersonId));
366	    }
367	
368	    /** A person's holds, in the order they were put on. */
369	    public List<PersonHold> holds(Long personId) {
370	        return holds.findByPersonIdOrderByIdAsc(personId);
371	    }
372	
373	    /** A person's holds as they stood at the end of a day: those put on while the sheet's today was
374	     *  on or before it, in the order they were put on. */
375	    public List<PersonHold> holdsAsOf(Long personId, LocalDate day) {
376	        return holds(personId).stream().filter(hold -> hold.madeAsOf(day)).toList();
377	    }
378	
379	    /** Each person's patron ids on the sheet, in the order they were named, by person id; a person
380	     *  with none is absent. */
381	    public Map<Long, List<Long>> patronIds(String sheetId) {
382	        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
383	                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
384	                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
385	    }
386	
387	    /** A person's patron ids, in the order they were named. */
388	    public List<Long> patronIds(Long personId) {
389	        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
390	    }
391	
392	    /** Name another person on the sheet as a person's patron; refused for the person themselves and
393	     *  for someone already their patron. */
394	    @Transactional
395	    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
396	        Person person = people.findByIdAndSheetId(id, sheetId)
397	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
398	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
399	                .orElseThrow(() -> new NoSuchElementException("No person " + patronId + " on sheet " + sheetId));
400	        if (person.getId().equals(patron.getId())) {
401	            throw new PatronRefusedException(person.getName() + " cannot be their own patron");
402	        }
403	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
404	            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
405	        }
406	        patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
407	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
408	                + " patron=" + patron.getName());
409	        return person;
410	    }
411	
412	    /** Start or stop a user watching a person; a person already in that state is left as they are,
413	     *  writing nothing. */
414	    @Transactional
415	    public Person watch(String sheetId, String user, Long id, boolean on) {
416	        Person person = people.findByIdAndSheetId(id, sheetId)
417	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
418	        var existing = watches.findByPersonIdAndUser(id, user);
419	        if (on && existing.isEmpty()) {
420	            watches.saveAndFlush(new PersonWatch(sheetId, id, user));
421	            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
422	        } else if (!on && existing.isPresent()) {
423	            watches.delete(existing.get());
424	            watches.flush();
425	            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
426	        }
427	        return person;
428	    }
429	
430	    /** The ids of the people a user watches on the sheet. */
431	    public Set<Long> watchedIds(String sheetId, String user) {
432	        return watches.findBySheetIdAndUser(sheetId, user).stream().map(PersonWatch::getPersonId)
433	                .collect(Collectors.toSet());
434	    }
435	
436	    /** Whether a user watches a person. */
437	    public boolean watches(Long personId, String user) {
438	        return watches.findByPersonIdAndUser(personId, user).isPresent();
439	    }
440	
441	    /** A person's watchers, in the order they started watching. */
442	    public List<String> watchers(Long personId) {
443	        return watches.findByPersonIdOrderByIdAsc(personId).stream().map(PersonWatch::getUser).toList();
444	    }
445	
446	    private void record(String event, String sheetId, String user, Person person, String grade, String terms) {
447	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
448	                + " name=" + person.getName() + " grade=" + grade + terms);
449	    }
450	
451	    private void requireFreeName(String sheetId, String name, Long exceptId) {
452	        if (people.nameInUse(sheetId, name, exceptId)) {
453	            throw new NameInUseException(name);
454	        }
455	    }
456	}
