638	package net.officefloor.hq.app.person;
639	
640	import java.time.LocalDate;
641	import java.util.Comparator;
642	import java.util.List;
643	import java.util.Map;
644	import java.util.Optional;
645	import java.util.stream.Collectors;
646	import net.officefloor.hq.app.history.History;
647	import org.springframework.stereotype.Service;
648	
649	/** The grades given to the people on a sheet, each in force from its from-date. */
650	@Service
651	public class PersonGradeService {
652	
653	    /** Grades from the earliest: no from-date first, then by from-date. */
654	    private static final Comparator<PersonGrade> FROM_EARLIEST =
655	            Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()));
656	
657	    private final PersonGradeRepository grades;
658	    private final History history;
659	
660	    public PersonGradeService(PersonGradeRepository grades, History history) {
661	        this.grades = grades;
662	        this.history = history;
663	    }
664	
665	    /** A person's grades, from the earliest. */
666	    public List<PersonGrade> of(Long personId) {
667	        return grades.findByPersonId(personId).stream().sorted(FROM_EARLIEST).toList();
668	    }
669	
670	    /** Each person's grades on the sheet, from the earliest, by person id. */
671	    public Map<Long, List<PersonGrade>> bySheet(String sheetId) {
672	        return grades.findBySheetId(sheetId).stream().sorted(FROM_EARLIEST)
673	                .collect(Collectors.groupingBy(PersonGrade::getPersonId));
674	    }
675	
676	    /** The person's grade in force on a date: the one whose from-date is the latest on or before it
677	     *  (the first grade applies from the beginning of time). */
678	    public String gradeOn(Long personId, LocalDate date) {
679	        return gradeOn(of(personId), date);
680	    }
681	
682	    /** The person's grade in force on a date as their grades stood at the end of a day (null: as
683	     *  they stand now). */
684	    public String gradeOn(Long personId, LocalDate date, LocalDate asOf) {
685	        return gradeOn(asOf == null ? of(personId) : history.grades(personId, asOf), date);
686	    }
687	
688	    /** The grade in force on a date among a person's grades; null when they have none. */
689	    public static String gradeOn(List<PersonGrade> theirs, LocalDate date) {
690	        return theirs.stream()
691	                .filter(g -> g.appliesOn(date))
692	                .max(FROM_EARLIEST)
693	                .map(PersonGrade::getGrade)
694	                .orElse(null);
695	    }
696	
697	    /** Give a person a grade from a date (null: from the beginning of time), replacing the one they
698	     *  had from that date and keeping the others. */
699	    public PersonGrade give(Person person, String grade, LocalDate from) {
700	        Optional<PersonGrade> had = from == null
701	                ? grades.findByPersonIdAndFromIsNull(person.getId())
702	                : grades.findByPersonIdAndFrom(person.getId(), from);
703	        PersonGrade given = had
704	                .map(existing -> {
705	                    existing.setGrade(grade);
706	                    return existing;
707	                })
708	                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), grade, from));
709	        return grades.saveAndFlush(given);
710	    }
711	}
